import React, { useState, useEffect } from 'react';
import SortableTree from '@nosferatu500/react-sortable-tree';
import '@nosferatu500/react-sortable-tree/style.css';
import './App.css';

// Recursively map 'name' → 'title'
function mapToTreeFormat(nodes) {
  return nodes.map(node => ({
    ...node,
    title: node.name,  // THIS IS KEY
    children: mapToTreeFormat(node.children || []),
  }));
}

function App() {
    const [treeData, setTreeData] = useState([]);

    useEffect(() => {
    fetch('http://localhost:8080/en/humancapital/organization/tree-data/')
        .then((res) => res.json())
        .then((data) => {
        const mappedData = mapToTreeFormat(data);
        setTreeData(mappedData);
        })
        .catch((error) => console.error('Error fetching tree data:', error));
    }, []);

  return (
    <div style={{ height: 600 }}>
      <h2 style={{ textAlign: 'center', margin: '20px 0' }}>Organization Tree</h2>
      <SortableTree
        treeData={treeData}
        onChange={setTreeData}
      />
    </div>
  );
}

export default App;
